import{t as e}from"./index-BLzR0iE1.js";var t=[{id:`banking`,num:`01`,name:`Banking & Finance`,desc:`Structured finance, syndicated lending, e-banking, insurance claims, and project financing across East Africa.`,lawyer:`Robert Kasaija`,image:`/assets/images/practice/banking-finance.jpg`,long:`We understand your insurance, banking and financing needs. Our practice includes general insurance banking, structured finance, syndicated and general lending, asset and project finance, guarantees, derivatives, debentures and charges. We have acted as counsel for numerous foreign and local investors, foreign donor agencies and government bodies.`},{id:`corporate`,num:`02`,name:`Corporate & Commercial`,desc:`Mergers, acquisitions, foreign investment, company secretarial work, and cross-border transactions.`,lawyer:`Justin Joseph Kasaija`,image:`/assets/images/practice/corporate-commercial.jpg`,long:`We are your partners in achieving your commercial and investment goals. Our firm has served as in-house counsel and company secretaries for foreign and local clients, handling equity and contractual joint ventures, wholly owned foreign enterprises, holding companies, and financial and management agreements.`},{id:`debt`,num:`03`,name:`Debt Recovery`,desc:`Proven recovery record for H.K Financial Services, Save and Invest, S.N Financial Services, and Twezimbe Investment Group.`,lawyer:`Sharon Murungi`,image:`/assets/images/practice/debt-recovery.jpg`,long:`The firm has recovered substantial sums on behalf of clients including H.K Financial Services Limited, Save and Invest Limited, S.N Financial Services Limited, Tin Link Financial Solutions, Agwotwe Financial Services, and Twezimbe Investment Group.`},{id:`land`,num:`04`,name:`Land & Conveyancing`,desc:`Title searches, mortgages, caveats, due diligence, and full transactional support for property transfers.`,lawyer:`Joseph Kwesiga`,image:`/assets/images/practice/land-conveyancing.jpg`,long:`We represent individuals and companies in land and property matters. We ensure due diligence searches to authenticate land particulars, handle sale and purchase transactions through final transfers, secure mortgage transactions, process special certificates of title, and lodge and lift caveats.`},{id:`ip`,num:`05`,name:`Intellectual Property`,desc:`Trademark and patent registration, enforcement, and Uganda's first unfair competition and predatory pricing action.`,lawyer:`Sharon Murungi`,image:`/assets/images/practice/intellectual-property.jpg`,long:`We handle property rights agreements, trademark and patent application procedures, declarations of use, and renewals. We successfully enforced IP rights in matters involving trademark violations, licensing and exploitation in Uganda, and handled the first unfair competition and predatory pricing action in the country.`},{id:`family`,num:`06`,name:`Family & Probate`,desc:`Divorce, custody, child maintenance, adoption, guardianship, wills, and succession.`,lawyer:`Sharon Murungi`,image:`/assets/images/practice/family-probate.jpg`,long:`We ensure your testamentary wishes are recorded and enforced. Our work covers trusts and estates, wills, succession, probate, divorce, separations, custody, child maintenance, adoption, and guardianship.`},{id:`employment`,num:`07`,name:`Employment & Labour`,desc:`Employment contracts, redundancies, trade union relations, pension audits, and managerial compensation.`,lawyer:`Sharon Murungi`,image:`/assets/images/practice/employment-labour.jpg`,long:`We know your most important relationships are with employers and employees. We advise on employment contracts, handling redundancies, trade union relations, remuneration and incentive systems, pension funds and social security audits, expatriation, and managerial compensation.`},{id:`criminal`,num:`08`,name:`Criminal Law`,desc:`Criminal defence, private investigations, and retained partnerships with leading security firms.`,lawyer:`Robert Kasaija`,image:`/assets/images/practice/criminal-law.jpg`,long:`We have represented clients in numerous criminal proceedings with an impressive record. We handle private investigations and are retained by security companies, conducting thorough investigative work that concludes cases efficiently.`},{id:`adr`,num:`09`,name:`Arbitration & ADR`,desc:`ICAMEK-accredited arbitration, mediation, and negotiation. Business-minded resolution over costly litigation.`,lawyer:`Robert Kasaija`,image:`/assets/images/practice/arbitration-adr.jpg`,long:`Our Managing Partner is a member of ICAMEK. We strongly believe in approaching clients' problems with business acumen — time is money, and we encourage clients to embrace alternative dispute resolution mechanisms wherever strategically appropriate.`},{id:`tax`,num:`10`,name:`Revenue Law & Taxation`,desc:`Corporate tax advisory, takeovers, reorganisations, and strategic tax planning for directors and shareholders.`,lawyer:`Robert Kasaija`,image:`/assets/images/practice/tax-revenue.jpg`,long:`We advise clients on varied tax issues with an emphasis on corporate matters including takeovers, mergers, reorganisations, financing, and privatisation, as well as tax planning for managing directors and shareholders.`},{id:`ngo`,num:`11`,name:`Non-Profit & NGO`,desc:`NGO formation, compliance, financing, and governance. Pro-bono partner of Uganda Christian Lawyers Fraternity.`,lawyer:`Joseph Kwesiga`,image:`/assets/images/practice/ngo-nonprofit.jpg`,long:`We work extensively with NGOs — from formation through financing, performance monitoring, and general legal work. We also provide pro-bono legal services to the Uganda Christian Lawyers Fraternity and the Uganda Law Society.`},{id:`compliance`,num:`12`,name:`Governance & Compliance`,desc:`Compliance programs, regulatory advisory, and integration of governance with operational requirements.`,lawyer:`Justin Joseph Kasaija`,image:`/assets/images/practice/governance-compliance.jpg`,long:`We monitor developments in this rapidly evolving area and advise institutional and individual clients on regulatory obligations. We design and implement compliance programs to deter inadvertent and purposeful failures to heed laws and regulations.`}],n=[{name:`Robert Kasaija`,role:`Managing Partner`,focus:`Corporate Finance · Real Estate · Arbitration · Litigation`,bio:`Over 20 years in legal practice. Commissioner for Oaths, Notary Public, ICAMEK arbitrator. Represents Shengli Engineering Company and numerous multinationals.`,creds:[`LLB (Hons), UCU`,`PGD Legal Practice, LDC`,`Justice Advocacy Cert. (Canada/USA)`,`Member — ICAMEK, ULS, EALS`],photo:e.advocates.robert.src,fallback:e.advocates.robert.fallback},{name:`Sharon Murungi`,role:`Partner — Head of Litigation`,focus:`Commercial · Labour · Tax · Arbitration · Family Law`,bio:`Head of Litigation and Dispute Resolution. Former protection manager at HIJRA/UNHCR and legal aid provider with the Uganda Christian Lawyers Fraternity.`,creds:[`LLB (Hons), UCU`,`PGD Legal Practice, LDC`,`Justice Advocacy Cert. (Canada/USA)`,`Member — ULS, EALS`],photo:e.advocates.sharon.src,fallback:e.advocates.sharon.fallback},{name:`Joseph Kwesiga`,role:`Partner`,focus:`Environmental · Land · Procurement · Insurance`,bio:`Legal Officer and Head of Prosecutions at the National Forestry Authority. Deep expertise in environmental litigation and procurement law.`,creds:[`LLB (Hons), UCU`,`PGD Legal Practice, LDC`,`Member — ULS, EALS`],photo:e.advocates.joseph.src,fallback:e.advocates.joseph.fallback},{name:`Justin Joseph Kasaija`,role:`Associate — Head of Administration`,focus:`Corporate Governance · Business Advisory`,bio:`Advises national and multinational companies on business planning and risk mitigation. Board member of Sage Buyers, Black Market Entertainment, Inveseed, and Koisan Investments.`,creds:[`LLB (Hons)`,`LDC (Hons)`,`Member — Rotary Kampala Metropolitan`],photo:e.advocates.justine.src,fallback:e.advocates.justine.fallback},{name:`Christopher Baluku`,role:`Associate`,focus:`Submissions · Pleadings · Research`,bio:`Well grounded in preparation of submissions and pleadings. Strong research contribution across the firm's litigation portfolio.`,creds:[`LLB (Hons)`,`LDC (Hons)`],photo:e.advocates.chris.src,fallback:e.advocates.chris.fallback},{name:`Fred Asiimwe`,role:`Associate`,focus:`Civil Litigation · Research`,bio:`Extensive experience in civil litigation, research, and preparation of pleadings.`,creds:[`LLB (Hons)`,`LDC (Hons)`],photo:e.advocates.fred.src,fallback:e.advocates.fred.fallback},{name:`Oscar Musiime`,role:`Associate`,focus:`Corporate & Commercial · IP · Family Law · Land Transactions`,bio:`Admitted as an Advocate of the High Court of Uganda. Brings a client-centred approach combining technical rigour with practical, results-driven counsel. Expertise spans corporate and commercial law, intellectual property, family law, and land transactions.`,creds:[`LLB (UCU)`,`PGD Legal Practice (LDC)`],photo:e.advocates.oscar.src,fallback:e.advocates.oscar.fallback}],r=[`Shengli Engineering`,`H.K Financial Services`,`Save and Invest`,`S.N Financial Services`,`Tin Link Financial`,`Twezimbe Investment`,`Agwotwe Financial`,`National Forestry Authority`];export{t as n,n as r,r as t};